// TH14 v1.00b stage 5 wave — st05.ecl.txt
// 源入口 MainSub02 (647-665) / MainSub02b (667-685，右路先等120)
// 依赖 Phantom02 (1108-1131) / Phantom02_at (1133-1180)
// 弹型：源 type8=TH14_RICE，color13（TH14 词表 0–23 同号）

const TIME_LIMIT: int = 1924;
const OPENING_BUFFER: int = 120;

const TH14_RICE: int = 480;
const RICE_COLOR: int = 13;

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

// 本卡没有整波中断；两路出生沿用各自原排程。
async sub pattern() {
    wait(OPENING_BUFFER);
    spawn spawn_route(0);
    spawn spawn_route(1);
}

// 源 MainSub02（左，657）/ MainSub02b（右，677，先 wait 120）：
// 每次创建 Phantom02，HP100；初间 60，每次减 5 直到 10；两路各 20 只。
// A=160、B=64 在源里从未被读取，不产生行为。
async sub spawn_route(side: int) {
    if side == 1 { wait(120); }
    var gap: int = 60;
    for n in 0..20 {
        // 同一条 enmCreate 内两次独立 %RANDF 读取：先 x 后 y。
        var ux: fx = ((rand(65536) - 32768) as fx) / 32768 * 0.5fx + 0.5fx;
        var uy: fx = ((rand(65536) - 32768) as fx) / 32768 * 0.5fx + 0.5fx;
        if side == 0 {
            // 657: enmCreate("Phantom02", -192 - RANDF*32, 192 + RANDF*64, ...)
            _ = spawn_enemy(-192fx - ux * 32fx, 192fx + uy * 64fx, 100, 0, 0, 0, phantom02(0));
        } else {
            // 677: enmCreateM(...) 右路镜像；出生坐标按输入值，镜像位只作用于子敌运动
            _ = spawn_enemy(192fx + ux * 32fx, 192fx + uy * 64fx, 100, 0, 0, 0, phantom02(1));
        }
        wait(gap);
        if gap > 10 { gap = gap - 5; }
    }
}

// 源 Phantom02 1108-1131 + Phantom02_at 1133-1180。
// mirror=1 对应 enmCreateM 的子镜像位：普通 moveVel 的 x 分量取反（角度 θ → 180°-θ）；
// 圆周层按已核口径不受镜像位影响。
async sub phantom02(mirror: int) {
    set_invuln(65535);
    set_hitbox(8fx);    // 1113 setHitbox(16,16)：普通圆形取第一值一半
    set_hurtbox(14fx);  // 1112 setHurtbox(28,28)：同上

    var d0: angle = 45deg;    // 1116 moveVel(45°, 4)
    var dstop: angle = 0deg;  // 1117 moveVelTime(30, 0, 0°, 0)
    var d1: angle = -45deg;   // 1119 moveVel(-45°, 0)
    if mirror == 1 {
        d0 = 135deg;
        dstop = 180deg;
        d1 = 225deg;
    }
    move_vel(0, d0, 4fx, EASE_LINEAR);
    move_vel(30, dstop, 0fx, EASE_LINEAR);
    wait(30);
    move_vel(0, d1, 0fx, EASE_LINEAR);

    // 1121 moveCircleRel(RANDRAD, 1°/帧, -90, 0)：REL 层圆，圆心在相位方向 90px 处，
    // 起始半径 -90（即从圆心反侧出发，REL=0）。
    var theta: angle = (rand(65536) - 32768) as angle;
    var cx: fx = 90fx * cos(theta);
    var cy: fx = 90fx * sin(theta);
    var xabs: fx = $self_x;
    var yabs: fx = $self_y;
    var k: int = 0;
    var spd: fx = 0fx;
    var rr: fx = -90fx;

    spawn phantom02_at();

    loop {
        k = k + 1;
        // 1120 moveSpeedTime(240, 1, 2)：mode1 = t²，到期保持 2px/帧
        spd = 2fx;
        if k < 240 {
            var q: fx = (k as fx) / 240fx;
            spd = 2fx * q * q;
        }
        xabs = xabs + spd * cos(d1);
        yabs = yabs + spd * sin(d1);
        // 相位每帧 +ω（ω 保持 1°/帧）
        theta = theta + 1deg;
        // 1122 moveCircleRelTime(80, 0, -999999, 16, 0)：r 由 -90 线性到 16，
        // ω=-999999 为该槽“保持原值”哨兵，d 保持 0。
        rr = 16fx;
        if k < 80 {
            var qr: fx = (k as fx) / 80fx;
            rr = -90fx + 106fx * qr;
        }
        // 目标无 REL 层：逐帧写 ABS+REL 合成位置
        move_to(0, xabs + cx + rr * cos(theta), yabs + cy + rr * sin(theta), EASE_LINEAR);
        wait(1);
    }
}

async sub phantom02_at() {
    var rank: int = global(GVAR_RANK);
    var lanes: int = 1;      // 1139-1148 etCount：E1 N1 H3 L3（层数1）
    var volleys: int = 10;   // 1159 diffI($C, 4, 10, 10, 10)：只驱动 etOn 轮数
    var spd: fx = 2.5fx;     // 1158 diffF(%A, 2.5, 2.5, 3.5, 4.5)
    var tail: int = 40;      // 1167-1175：E 100，其余 40
    if rank == RANK_EASY { volleys = 4; tail = 100; }
    if rank >= RANK_HARD { lanes = 3; spd = 3.5fx; }
    if rank >= RANK_LUNATIC { spd = 4.5fx; }

    // 1136-1152 只配置发射器，没有 etOn；首轮发射在 1163。
    // 1153 等 60 帧后 1157 取一次自机角（模式1 固定角），1159 定轮数。
    wait(60);
    var base: angle = aim_player();
    for v in 0..volleys {
        for j in 0..lanes {
            // 1157 第二参 10°；模式1 扇形 F(K,j)（K 为奇数：0, -10°, +10°）
            var h: int = ((j + 1) / 2) * 1820;
            if j % 2 != 0 { h = -h; }
            var a: angle = base + (h as angle);
            // 1152 etEx type2 a=1：出生退位移 4*速度，沿各弹自身角度
            _ = fire(TH14_RICE, RICE_COLOR,
                     $self_x - 4fx * spd * cos(a), $self_y - 4fx * spd * sin(a),
                     spd, a, none, none);
        }
        wait(10);
    }
    wait(tail);
}
